import {applyParameterPreset} from './field-controls.mjs';
export const MAX_PRESET_BYTES=256*1024;
const number=(min,max)=>({kind:'number',min,max}),choice=values=>({kind:'choice',values});
export const ENGINE_FIELDS={mode:choice(['islands','global','modular']),coupling:number(0,8),noise:number(0,2),drift:number(0,2),projection:choice([-1,0,1]),pulseMode:choice(['regional','brainstorm','rain']),pulseEnabled:{kind:'boolean'},pulseRate:number(.25,12),pulseJitter:number(0,1),pulseStrength:number(0,1),attack:number(.03,2),decay:number(.03,4),sustain:number(0,1),release:number(.03,5)};
export const ORBIT_DEFAULTS={orbitEnabled:false,orbitRate:.07,orbitDepth:.7};
export const AUDIO_FIELDS={orbitEnabled:{kind:'boolean'},orbitRate:number(.01,.5),orbitDepth:number(0,1),tuningMode:choice(['locked','free']),root:number(32.703,1046.503),scale:choice(['minor','major','fifths']),detune:number(0,100),tone:number(0,1),space:number(0,1),output:number(0,1),reverb:number(0,1),reverbSize:number(0,1),spread:number(0,1),variation:number(0,1),octaves:choice([0,1,2,3]),voiceLimit:choice([4,8,16]),binaural:{kind:'boolean'},droneEnabled:{kind:'boolean'},difference:number(2,50)};
const own=(object,key)=>Object.prototype.hasOwnProperty.call(object,key);
function record(value,label){if(!value||typeof value!=='object'||Array.isArray(value)||![Object.prototype,null].includes(Object.getPrototypeOf(value)))throw new Error(label+' must be an object.');}
function cleanFields(source,schema,label){record(source,label);const clean={};for(const [key,rule]of Object.entries(schema)){if(!own(source,key))throw new Error('Missing '+label+'.'+key+'.');const value=source[key];if(rule.kind==='boolean'){if(typeof value!=='boolean')throw new Error(label+'.'+key+' must be true or false.');clean[key]=value;}else if(rule.kind==='choice'){if(!rule.values.includes(value))throw new Error('Invalid '+label+'.'+key+'.');clean[key]=value;}else{if(typeof value!=='number'||!Number.isFinite(value))throw new Error(label+'.'+key+' must be a finite number.');const epsilon=Number.EPSILON*16*Math.max(1,Math.abs(rule.min),Math.abs(rule.max));if(value<rule.min-epsilon||value>rule.max+epsilon)throw new Error(label+'.'+key+' is outside its range.');clean[key]=Math.max(rule.min,Math.min(rule.max,value));}}return clean;}
export function validateUserPreset(value,{allowLegacyFactory=false}={}){
 record(value,'Preset');for(const key of ['version','name','engine','audio'])if(!own(value,key))throw new Error('Missing preset '+key+'.');const legacy=allowLegacyFactory&&!own(value,'format')&&value.name==='D Major Drift'&&own(value,'capturedFrom')&&own(value,'nativeMapping');if((!own(value,'format')&&!legacy)||(own(value,'format')&&value.format!=='cortex65-preset'))throw new Error('Not a CORTEX / 65 preset file.');if(value.version!==1)throw new Error('Unsupported preset version.');if(typeof value.name!=='string'||value.name.trim().length<1||value.name.trim().length>80)throw new Error('Preset name must contain 1–80 characters.');record(value.audio,'audio');const orbitKeys=Object.keys(ORBIT_DEFAULTS),present=orbitKeys.filter(key=>own(value.audio,key)).length;if(present!==0&&present!==3)throw new Error('Incomplete headphone orbit settings.');const audioSource=Object.create(null);for(const key of Object.keys(AUDIO_FIELDS)){if(own(value.audio,key))audioSource[key]=value.audio[key];else if(present===0&&own(ORBIT_DEFAULTS,key))audioSource[key]=ORBIT_DEFAULTS[key];}const audio=cleanFields(audioSource,AUDIO_FIELDS,'audio');if(audio.orbitEnabled)audio.binaural=false;return{format:'cortex65-preset',version:1,name:value.name.trim(),engine:cleanFields(value.engine,ENGINE_FIELDS,'engine'),audio};
}
export function parseUserPreset(text){if(typeof text!=='string')throw new Error('Preset file must contain JSON text.');if(new TextEncoder().encode(text).byteLength>MAX_PRESET_BYTES)throw new Error('Preset file exceeds 256 KiB.');let value;try{value=JSON.parse(text);}catch{throw new Error('Invalid preset JSON.');}return validateUserPreset(value,{allowLegacyFactory:true});}
export function serializeUserPreset(value){return JSON.stringify(validateUserPreset(value),null,2)+'\n';}
export function loadUserPreset(text,adapter){const preset=parseUserPreset(text);applyParameterPreset(preset,adapter);return preset;}
export function presetFilename(name){return(name.replace(/[\\/:*?"<>|\u0000-\u001f]/g,'-').replace(/\s+/g,' ').replace(/[. ]+$/g,'').trim()||'CORTEX-65')+'.cortex65.json';}
export function capturePresetFromDom(doc,parameters,name){
 const selected=(id,data)=>doc.getElementById(id).querySelector('button.selected').dataset[data],value=id=>doc.getElementById(id).value,toggle=id=>doc.getElementById(id).getAttribute('aria-pressed')==='true';const engine={},audio={};
 for(const key of Object.keys(ENGINE_FIELDS))engine[key]=parameters[key];for(const key of Object.keys(AUDIO_FIELDS))audio[key]=parameters[key];
 Object.assign(engine,{mode:selected('modes','mode'),projection:Number(selected('projections','projection')),pulseMode:value('pulse-mode'),pulseEnabled:toggle('pulse-enabled')});
 Object.assign(audio,{tuningMode:selected('tuning-modes','tuning'),root:Number(value('root')),scale:value('scale'),voiceLimit:Number(value('voice-limit')),octaves:Number(value('octaves')),orbitEnabled:toggle('orbit-enabled'),binaural:toggle('binaural-enabled'),droneEnabled:toggle('drone-enabled')});
 return validateUserPreset({format:'cortex65-preset',version:1,name,engine,audio});
}
